-- DREAM CAMPUS 서울 소재 대학 기본정보 적재용 SQL
-- Source CSV data_date: 2026-03-18; reference year: 2025
-- Scope: 시도명=서울특별시 and 대학구분명 IN ('대학','전문대학'); 대학원 과정 제외
-- Note: one institution may have multiple campus/location rows.

CREATE TABLE IF NOT EXISTS universities (
  university_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  school_name VARCHAR(200) NOT NULL,
  school_name_en VARCHAR(300) NULL,
  university_category VARCHAR(30) NOT NULL,
  school_category VARCHAR(50) NOT NULL,
  establishment_type VARCHAR(30) NULL,
  homepage VARCHAR(500) NULL,
  established_date DATE NULL,
  reference_year SMALLINT NULL,
  data_reference_date DATE NULL,
  provider_code VARCHAR(30) NULL,
  provider_name VARCHAR(200) NULL,
  PRIMARY KEY (university_id),
  UNIQUE KEY uq_universities_school_name (school_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS university_campuses (
  campus_id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  university_id BIGINT UNSIGNED NOT NULL,
  branch_type VARCHAR(30) NULL,
  sido_code VARCHAR(10) NULL,
  sido_name VARCHAR(50) NOT NULL,
  road_address VARCHAR(500) NULL,
  lot_address VARCHAR(500) NULL,
  road_postcode VARCHAR(20) NULL,
  lot_postcode VARCHAR(20) NULL,
  phone VARCHAR(50) NULL,
  fax VARCHAR(50) NULL,
  PRIMARY KEY (campus_id),
  UNIQUE KEY uq_university_campus_address (university_id, road_address),
  CONSTRAINT fk_university_campuses_university FOREIGN KEY (university_id) REFERENCES universities(university_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

START TRANSACTION;

-- 1) Institution master: one row per distinct school name
ON DUPLICATE KEY UPDATE
  school_name_en=VALUES(school_name_en), university_category=VALUES(university_category), school_category=VALUES(school_category), establishment_type=VALUES(establishment_type), homepage=VALUES(homepage), established_date=VALUES(established_date), reference_year=VALUES(reference_year), data_reference_date=VALUES(data_reference_date), provider_code=VALUES(provider_code), provider_name=VALUES(provider_name);

-- 2) Campus/location rows; link each address to its university master row
ON DUPLICATE KEY UPDATE branch_type=VALUES(branch_type), sido_code=VALUES(sido_code), sido_name=VALUES(sido_name), lot_address=VALUES(lot_address), road_postcode=VALUES(road_postcode), lot_postcode=VALUES(lot_postcode), phone=VALUES(phone), fax=VALUES(fax);

COMMIT;

